  }
  if (n_inp) {
    q.memcpy(d_inp, inp, sizeof(int) * n_inp).wait();
  }

  const int variants[] = {1, 2};
  for (int vi = 0; vi < 2; ++vi) {
    const int k = variants[vi];
    if (n_wte) {
      q.memset(d_dwte, 0, sizeof(float) * n_wte).wait();
    }
