      std::fwrite(dwte, sizeof(float), n_wte, fout);
    }
    if (n_wpe) {
      q.memcpy(dwpe, d_dwpe, sizeof(float) * n_wpe).wait();
      std::fwrite(dwpe, sizeof(float), n_wpe, fout);
    }
  }

